create extension if not exists "pgcrypto";
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,email text,full_name text,role text default 'user',created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists stories(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,title text not null,summary text,age_group text,language text,theme text,setting text,hero_name text,hero_type text,moral text,tone text,length text,page_count integer default 3,has_images boolean default true,has_audio boolean default true,status text default 'completed',raw_prompt jsonb,story_json jsonb,error_message text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists story_pages(id uuid primary key default gen_random_uuid(),story_id uuid references stories(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,page_number integer not null,page_text text not null,tts_script text,illustration_prompt text,image_storage_path text,image_signed_url text,audio_storage_path text,audio_signed_url text,estimated_reading_time_seconds integer,image_status text default 'pending',audio_status text default 'pending',created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists story_characters(id uuid primary key default gen_random_uuid(),story_id uuid references stories(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,name text,role text,description text,visual_anchor_prompt text,anchor_image_storage_path text,anchor_image_signed_url text,created_at timestamptz default now());
create table if not exists usage_logs(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,story_id uuid references stories(id) on delete set null,action text not null,model text,input_tokens integer,output_tokens integer,image_count integer default 0,audio_count integer default 0,estimated_cost_usd numeric,metadata jsonb,created_at timestamptz default now());
create table if not exists user_quotas(user_id uuid primary key references auth.users(id) on delete cascade,text_stories_used_today integer default 0,illustrated_stories_used_today integer default 0,images_used_today integer default 0,audio_generations_used_today integer default 0,last_reset_date date default current_date,created_at timestamptz default now(),updated_at timestamptz default now());
alter table profiles enable row level security;alter table stories enable row level security;alter table story_pages enable row level security;alter table story_characters enable row level security;alter table usage_logs enable row level security;alter table user_quotas enable row level security;
create policy "profiles select own" on profiles for select using (auth.uid()=id);create policy "profiles insert own" on profiles for insert with check (auth.uid()=id);create policy "profiles update own" on profiles for update using (auth.uid()=id);
create policy "stories select own" on stories for select using (auth.uid()=user_id);create policy "stories insert own" on stories for insert with check (auth.uid()=user_id);create policy "stories update own" on stories for update using (auth.uid()=user_id);create policy "stories delete own" on stories for delete using (auth.uid()=user_id);
create policy "pages select own" on story_pages for select using (auth.uid()=user_id);create policy "pages insert own" on story_pages for insert with check (auth.uid()=user_id);create policy "pages update own" on story_pages for update using (auth.uid()=user_id);create policy "pages delete own" on story_pages for delete using (auth.uid()=user_id);
create policy "characters select own" on story_characters for select using (auth.uid()=user_id);create policy "characters insert own" on story_characters for insert with check (auth.uid()=user_id);create policy "characters update own" on story_characters for update using (auth.uid()=user_id);create policy "characters delete own" on story_characters for delete using (auth.uid()=user_id);
create policy "usage select own" on usage_logs for select using (auth.uid()=user_id);create policy "quota select own" on user_quotas for select using (auth.uid()=user_id);
